/* Quill Design System Theme
   Install: npx shadcn add https://www.quilldesignsystem.com/r/quill.json
   Fonts: Fraunces (display/heading) + Raleway (body) from Google Fonts
   Wiring: import this file from INSIDE the stylesheet that holds @import "tailwindcss",
   as its LAST line (@import "./quill-theme.css"). The last definition wins, and shadcn
   init writes its own dark line and radius lines (--radius-md: calc(var(--radius) * 0.8))
   that beat Quill's when they come after it. Imported from a layout instead, the colours
   still apply but every Quill utility (font-heading, the role classes, dark:) is dead —
   Tailwind never sees the @theme block below.
*/

/* ─── Font imports ──────────────────────────────────────────────────────────── */
@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght,SOFT,WONK@0,9..144,300..900,0..100,0..1;1,9..144,300..900,0..100,0..1&family=Raleway:wght@400;500;600&display=swap');

/* @quill-tokens:start */
