/* ── Base typography ────────────────────────────────────────────────────────── */
/* In @layer base so Tailwind text-* utilities override these element defaults.
   (Unlayered, they outrank the utilities layer in Tailwind v4 — e.g. a link-
   styled CTA's text-color utility was being ignored.) */
@layer base {
  body {
    font-family: "Raleway", -apple-system, BlinkMacSystemFont, sans-serif;
    line-height: var(--leading-reading);
    color: var(--ink-soft);
    background-color: var(--paper);
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: "Fraunces", Georgia, serif;
    font-weight: 400;
    letter-spacing: var(--tracking-display);
    line-height: var(--leading-heading);
    color: var(--ink);
    font-variation-settings: var(--fraunces-text);
  }

  h1 {
    line-height: var(--leading-display);
    font-variation-settings: var(--fraunces-display);
  }

  /* Fraunces set by class (`font-heading` on a CardTitle, a stat figure, a wordmark)
     takes the same text preset as h2–h6, so every Fraunces text is soft and one rule
     describes it. h1–h6 are excluded: the element rules above carry their presets
     (h1 = display). .fraunces-accent / .fraunces-caption are unlayered and still win. */
  .font-heading:not(h1, h2, h3, h4, h5, h6) {
    font-variation-settings: var(--fraunces-text);
  }

  /* Raleway's default digits are old-style and uneven in width, so dates, codes, amounts
     and counts bounced and their columns did not line up. Where numbers are data they sit
     on the line at one width; running text keeps old-style. Setting --tw-numeric-figure
     too makes the stock `tabular-nums` utility, which leaves it empty, lining as well. */
  [data-slot=calendar], [data-slot=table], [data-slot=input-otp], [data-slot=input-otp-group], [data-slot=chart], [data-slot=progress], [data-slot=avatar-group-count], .tabular-nums {
    --tw-numeric-figure: lining-nums;
    font-variant-numeric: lining-nums tabular-nums;
  }

  /* An avatar group's +N count: centred by its line box, the digits sat 1px high (the box keeps
     room above cap height that numerals never fill). 2px of top padding moves the centred text
     down 1px, measured on-centre at all three avatar sizes. A count showing an icon is left alone. */
  [data-slot=avatar-group-count]:not(:has(> svg)) {
    padding-top: var(--space-0_5);
  }

  /* Accent-text alias — follows data-accent, defaults to moss-deep; every
     accent cut meets WCAG AA (4.5:1) on paper backgrounds. */
  a { color: var(--text-accent-color); }
}

/* ── Utility classes ────────────────────────────────────────────────────────── */
.fraunces-display  { font-variation-settings: var(--fraunces-display); }
.fraunces-accent   { font-variation-settings: var(--fraunces-accent); font-style: italic; color: var(--text-accent-color); }
.fraunces-text     { font-variation-settings: var(--fraunces-text); }
.fraunces-caption  { font-variation-settings: var(--fraunces-caption); font-style: italic; color: var(--ink-muted); }
